import{_ as e,o as a,c as s,a5 as o}from"./chunks/framework.BmD0ICqc.js";const r="/study/images/os/files-and-paths.svg",g=JSON.parse('{"title":"ファイルとパス — 名前からデータを開くまで","description":"","frontmatter":{"title":"ファイルとパス — 名前からデータを開くまで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"ファイルのバイト列、ディレクトリ、絶対パスと相対パスを、ゲームの素材とセーブデータで説明する。拡張子、文字コード、開いて読み書きして閉じる流れにもつなげる。","aliases":["ファイル","ディレクトリ","フォルダー","パス","絶対パス","相対パス","カレントディレクトリ","拡張子","テキストファイル","バイナリファイル","文字コード","open","close"],"verification":"MicrosoftのWindowsファイル命名・パス形式・ファイル操作・文字エンコードの資料に照合（2026-11-07）"}},"headers":[],"relativePath":"os/files-and-paths.md","filePath":"os/files-and-paths.md"}'),n={name:"os/files-and-paths.md"};function d(i,t,l,c,p,h){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="ファイルとパス-—-名前からデータを開くまで" tabindex="-1">ファイルとパス — 名前からデータを開くまで <a class="header-anchor" href="#ファイルとパス-—-名前からデータを開くまで" aria-label="Permalink to &quot;ファイルとパス — 名前からデータを開くまで&quot;">​</a></h1><p>ゲーム本体、画像、セーブデータはストレージ上のファイルとして保存できます。アプリから見ると、通常のデータファイルは順に並んだバイト列です。名前や保存場所を管理する仕組みをファイルシステムと呼びます。ファイルをまとめる場所がディレクトリで、画面上ではフォルダーとも呼びます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/naming-a-file" target="_blank" rel="noreferrer">Microsoftのファイルとディレクトリ</a> · <a href="/study/data/integer-bits-and-bytes.html">ビットとバイト</a></p><h2 id="名前と保存場所をつなぐパス" tabindex="-1">名前と保存場所をつなぐパス <a class="header-anchor" href="#名前と保存場所をつなぐパス" aria-label="Permalink to &quot;名前と保存場所をつなぐパス&quot;">​</a></h2><p><strong>パス</strong>は、操作するファイルやディレクトリを指定する文字列です。ここではWindowsの説明用の配置を使います。<code>D:\\Game</code>以下に、ゲーム本体、画像用の<code>assets</code>、セーブ用の<code>saves</code>がある例です。<a href="https://learn.microsoft.com/en-us/dotnet/standard/io/file-path-formats" target="_blank" rel="noreferrer">MicrosoftのWindowsのパス形式</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Game</span></span>
<span class="line"><span>├─ game.exe</span></span>
<span class="line"><span>├─ assets</span></span>
<span class="line"><span>│  └─ player.png</span></span>
<span class="line"><span>└─ saves</span></span>
<span class="line"><span>   └─ slot1.json</span></span></code></pre></div><p><strong>絶対パス</strong>は、<code>D:\\Game\\assets\\player.png</code>のように、ドライブのルートから場所を指定します。<strong>相対パス</strong>は、<code>assets\\player.png</code>のように、基準となるディレクトリから場所を指定します。一般的なファイルAPIでは、この基準がプロセスの<strong>カレントディレクトリ</strong>です。<a href="https://learn.microsoft.com/en-us/dotnet/standard/io/file-path-formats#traditional-dos-paths" target="_blank" rel="noreferrer">Microsoftの絶対パスと相対パス</a></p><figure class="study-figure"><img src="`+r+'" alt="DドライブのGameフォルダーにはgame.exe、assets内のplayer.png、saves内のslot1.jsonがある。カレントディレクトリがD:\\Gameなら、相対パスassets\\player.pngは絶対パスD:\\Game\\assets\\player.pngを指す。" width="760" height="450" loading="lazy"><figcaption>ファイル名だけでなく、どのディレクトリを基準にするかが場所を決めます。<a href="/study/images/os/files-and-paths.svg" target="_blank" rel="noopener noreferrer">ディレクトリとパスの図を拡大</a></figcaption></figure><table tabindex="0"><thead><tr><th>表記</th><th>この例で示すもの</th></tr></thead><tbody><tr><td><code>D:\\Game\\assets\\player.png</code></td><td>ドライブから指定した画像の絶対パス。</td></tr><tr><td><code>assets\\player.png</code></td><td>カレントが<code>D:\\Game</code>なら、同じ画像への相対パス。</td></tr><tr><td><code>.</code></td><td>カレントディレクトリ。</td></tr><tr><td><code>..</code></td><td>一つ上のディレクトリ。</td></tr></tbody></table><p>アプリを起動した場所や起動方法で、カレントディレクトリは変わり得ます。EXEが置かれたディレクトリが、常に相対パスの基準になるわけではありません。また、<code>D:Game</code>は<code>D:\\Game</code>と意味が異なり、ドライブを指定した相対パスです。<a href="https://learn.microsoft.com/en-us/dotnet/standard/io/file-path-formats" target="_blank" rel="noreferrer">Microsoftのパス形式とカレントディレクトリ</a> · <a href="/study/tools/terminal-shell-and-commands.html">ターミナル・シェル・コマンド</a></p><h2 id="拡張子とファイルの中身" tabindex="-1">拡張子とファイルの中身 <a class="header-anchor" href="#拡張子とファイルの中身" aria-label="Permalink to &quot;拡張子とファイルの中身&quot;">​</a></h2><p><code>player.png</code>の<code>.png</code>や<code>slot1.json</code>の<code>.json</code>のような末尾を<strong>拡張子</strong>と呼びます。形式や開くアプリを選ぶ手がかりになります。ファイル名を<code>player.txt</code>へ変えても、中の画像データが文章へ変換されることはありません。読むアプリは、その形式の規則に従って中身を解釈します。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/naming-a-file#file-and-directory-names" target="_blank" rel="noreferrer">Microsoftのファイル名と拡張子</a> · <a href="/study/data/binary-file-validation.html">バイナリ形式の検証</a></p><p><strong>テキストファイル</strong>は、バイト列を文字コードの規則で文字として読むファイルです。例えばUTF-8は文字をバイト列へ表す方法の一つです。画像などの<strong>バイナリファイル</strong>では、寸法、色、圧縮データなどを、その形式が決めた値として読み取ります。どちらも保存されている内容はバイト列です。<a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/character-encoding-introduction" target="_blank" rel="noreferrer">Microsoftの文字エンコード</a> · <a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a></p><h2 id="開く、読み書きする、閉じる" tabindex="-1">開く、読み書きする、閉じる <a class="header-anchor" href="#開く、読み書きする、閉じる" aria-label="Permalink to &quot;開く、読み書きする、閉じる&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>アプリがすること</th></tr></thead><tbody><tr><td><strong>開く</strong></td><td>パスと、読み取り・書き込みなどの利用方法を指定する。成功すると、ハンドルやストリームなど、以後の操作に使うものを得る。</td></tr><tr><td><strong>読む</strong></td><td>指定した範囲のバイトを、アプリのメモリへ受け取る。</td></tr><tr><td><strong>書く</strong></td><td>アプリが用意したバイトを、ファイルの指定位置へ渡す。</td></tr><tr><td><strong>閉じる</strong></td><td>そのハンドルやストリームの利用を終え、関連する資源を解放する。</td></tr></tbody></table><p>開くときには、指定したファイルがあるか、操作が許可されているかなどをOSが確認します。書き込みでファイルを新しく作るか、既存の内容を置き換えるかは、APIに渡す指定で変わります。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/creating-and-opening-files" target="_blank" rel="noreferrer">Microsoftのファイル作成とオープン</a></p><p>読み取ったバイトは、ゲームが画像やセーブ内容として解釈します。また、閉じる処理と、突然電源が切れても保存内容が残る保証は、別に検討します。読み取りの内部は<a href="/study/os/file-read-journey.html">ファイルを読むと内部で何が起きるか</a>、保存の完了は<a href="/study/os/file-write-and-durability.html">ファイル書き込みと永続化</a>、ハンドルは<a href="/study/os/windows-handles.html">Windowsのハンドル</a>で扱います。</p>',16)])])}const m=e(n,[["render",d]]);export{g as __pageData,m as default};
